    centers=Chem.FindMolChiralCenters(m, includeUnassigned=True, useLegacyImplementation=False)
    c=Chem.MolToSmiles(m,isomericSmiles=True)
    # meso test
    mi=Chem.MolFromSmiles(c)
    Chem.AssignStereochemistry(mi,cleanIt=True,force=True)
    for a in mi.GetAtoms():
        if a.GetChiralTag()==Chem.ChiralType.CHI_TETRAHEDRAL_CW: a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CCW)
