const sc = `from rdkit import Chem
from rdkit.Chem import rdDetermineBonds
import numpy as np
def analyze(path,label):
    m=Chem.MolFromXYZFile(path); rdDetermineBonds.DetermineBonds(m,charge=0)
    Chem.AssignStereochemistryFrom3D(m)
    conf=m.GetConformer(); ri=m.GetRingInfo()
    print(label,"canon:",Chem.MolToSmiles(Chem.RemoveHs(m),isomericSmiles=True))
    print("   first8 elements:",[a.GetSymbol() for a in m.GetAtoms()][:8])
    print("   double bonds:",[(b.GetBeginAtomIdx()+1,b.GetEndAtomIdx()+1,str(b.GetStereo())) for b in m.GetBonds() if b.GetBondType()==Chem.BondType.DOUBLE])
    if ri.NumRings()>=1:
        ring=list(ri.AtomRings()[0]); ringset=set(ring)
        methyls=[(i,nb.GetIdx()) for i in ring for nb in m.GetAtomWithIdx(i).GetNeighbors() if nb.GetIdx() not in ringset and nb.GetSymbol()=="C"]
        pts=np.array([list(conf.GetAtomPosition(i)) for i in ring]); cen=pts.mean(axis=0); u,s,vt=np.linalg.svd(pts-cen); n=vt[2]
        sd=lambda i: float(np.dot(np.array(list(conf.GetAtomPosition(i)))-cen,n))
        if len(methyls)==2:
            a,b=sd(methyls[0][1]),sd(methyls[1][1])
            print("   ring",ring,"methyl sides %+.3f %+.3f -> %s"%(a,b,"CIS" if a*b>0 else "TRANS"))
    print("   CIP:",[(a.GetIdx()+1,a.GetProp("_CIPCode")) for a in m.GetAtoms() if a.HasProp("_CIPCode")])
analyze("ts_prep/product_cis.xyz","CORRECTED cis product")
analyze("ts_prep/reactant_cisoid_seed.xyz","REACTANT cisoid seed")
`;
